def from_generated(co):
    """For a point of the new head: the generated surface's class and point in head_input.png nearest it."""
    loc, _, fi, _ = GEN_BVH.find_nearest(co, 0.05)
    if fi is None:
        return head_shape.SKIN, None
    c, uvs, pts = GEN_FACES[fi]
    w = poly_3d_calc(pts, loc)
    u = sum((uv * x for uv, x in zip(uvs, w)), Vector((0, 0)))
    return c, (u.x * 1024, (1 - u.y) * 1024)


